import type { KeyObject } from "node:crypto";
import { FaydaError } from "./fayda.errors";
import { FaydaJwsAlg, SUPPORTED_JWS_ALGS, importPrivateKey } from "./fayda.jose";
import { isFaydaProductionHost } from "./fayda.tls";

export const FAYDA_OPTIONS = Symbol("FAYDA_OPTIONS");

/** The acr EDR asks for: a code generated by the Fayda app or channel. */
export const FAYDA_DEFAULT_ACR = "mosip:idp:acr:generated-code";
/** EDR's freight scope. `profile` covers name, birthdate, gender, picture. */
export const FAYDA_DEFAULT_SCOPE = "openid profile email phone address";
/** The userinfo claims EDR asks for, every one essential, in EDR's order. */
export const FAYDA_DEFAULT_USERINFO_CLAIMS = [
  "name",
  "phone_number",
  "email",
  "birthdate",
  "gender",
  "address",
  "nationality",
  "picture",
] as const;

export interface FaydaClientAssertionOptions {
  /** Default RS256, as EDR signs. PS256 only if NIDP registered the key for it. */
  alg?: "RS256" | "PS256";
  /**
   * Default false: the header is {alg} (plus kid when keyId is set), as EDR's freight copy and
   * NIDP's reference implementation send it. true adds typ JWT, as EDR's passenger copy does.
   */
  typ?: boolean;
  /** Default true: a random jti in every assertion. EDR sends none. false drops it. */
  jti?: boolean;
  /** Default 120, as EDR. */
  lifetimeSeconds?: number;
}

export interface FaydaBrowserBindingOptions {
  /**
   * Channels whose sessions are not bound to the starting browser, because no cookie survives
   * the trip (a native app). Default ["MOBILE"]. Every other channel needs the binding cookie
   * at completion.
   */
  unboundChannels?: string[];
  /** Default "fayda_b_". The cookie name is this plus 16 hex characters derived from the state. */
  cookiePrefix?: string;
  /** Default "/". */
  cookiePath?: string;
  /** Default true. false only for plain-http local development. */
  secureCookie?: boolean;
  /** Default "Lax": sent on eSignet's top-level redirect back, not on cross-site sub-requests. */
  sameSite?: "Lax" | "Strict" | "None";
}

export interface FaydaProofOptions {
  /** HMAC secret for proofs (FAYDA_PROOF_SECRET). At least 32 characters. */
  secret: string;
  /** Older secrets still accepted while a rotation runs. */
  previousSecrets?: string[];
  /** Default 15. EDR's passenger copy: 120. */
  ttlMinutes?: number;
}

export interface FaydaModuleOptions {
  /** Default true. false: start refuses (FAYDA_DISABLED) and completion answers FAYDA_DISABLED. */
  enabled?: boolean;
  /** Issued by NIDP (FAYDA_CLIENT_ID). Required. */
  clientId: string;
  /** The ID token's iss, exactly (FAYDA_ISSUER). Required: EDR never checked it. */
  issuer: string;
  /** FAYDA_AUTHORIZATION_ENDPOINT. Required. */
  authorizationEndpoint: string;
  /** FAYDA_TOKEN_ENDPOINT, also the client assertion's aud. Required. */
  tokenEndpoint: string;
  /** FAYDA_USERINFO_ENDPOINT. Required. */
  userinfoEndpoint: string;
  /** eSignet's key set (FAYDA_JWKS_URI). Required: EDR never fetched it. */
  jwksUri: string;
  /**
   * Our RSA private key for the client assertion: a JWK object, JWK JSON text, base64 of the JWK
   * JSON (EDR's FAYDA_PRIVATE_KEY_BASE64), or PEM. Required. Never logged or returned.
   */
  privateKey: unknown;
  /** kid on the client assertion (FAYDA_PRIVATE_KEY_ID). Default none, as EDR. */
  keyId?: string;
  /**
   * The exact redirect_uri per channel, each registered with NIDP, for example
   * { WEB: "https://office.example/fayda/callback", PORTAL: "...", MOBILE: "..." }. The one used
   * is stored with the session and sent again, verbatim, in the token call. Never taken from a
   * request. Required, at least one.
   */
  redirectUris: Record<string, string>;
  /** Default: "WEB" when listed, else the first key of redirectUris. */
  defaultChannel?: string;
  /**
   * Where the built-in GET callback sends the browser afterwards, per channel. Success gets
   * ?result=<session id>, failure ?error=<code>; nothing else, no claims, no tokens. Without an
   * entry for the channel, the callback answers JSON instead.
   */
  returnUrls?: Record<string, { success: string; failure: string }>;
  /** Default FAYDA_DEFAULT_SCOPE. */
  scope?: string;
  /** Default FAYDA_DEFAULT_ACR. Space-separated. */
  acrValues?: string;
  /** Default "en am". */
  claimsLocales?: string;
  /** Not sent by default. */
  uiLocales?: string;
  /** The userinfo claims requested, each essential. Default FAYDA_DEFAULT_USERINFO_CLAIMS. */
  userinfoClaims?: string[];
  /**
   * Default "login", as EDR's passenger copy sends it: a fresh sign-in at eSignet, so a second
   * person on the same device cannot silently get the first one's identity. false: not sent
   * (EDR's freight copy).
   */
  prompt?: "login" | "consent" | "select_account" | false;
  /** Default 10, as EDR. */
  sessionTtlMinutes?: number;
  /** Allowed clock difference for exp, iat and nbf. Default 60. */
  clockSkewSeconds?: number;
  /** Default ["RS256"]. */
  idTokenAlgs?: FaydaJwsAlg[];
  /** Default ["RS256"]. */
  userinfoAlgs?: FaydaJwsAlg[];
  /** Default true: a token answer without an id_token is refused. */
  requireIdToken?: boolean;
  /** Default true: an ID token without the session's nonce is refused. */
  requireNonce?: boolean;
  /** Default false: when true, the ID token's acr must be one of acrValues. */
  enforceAcr?: boolean;
  /**
   * Default false: userinfo answered as plain JSON (not a signed JWT) is refused. EDR accepted
   * it. Turn on only if NIDP confirms eSignet answers JSON for your client; its claims then rest
   * on TLS alone.
   */
  acceptJsonUserinfo?: boolean;
  clientAssertion?: FaydaClientAssertionOptions;
  /** For each call to eSignet, connection included. Default 10000. EDR had none. */
  httpTimeoutMs?: number;
  /** Default 10. */
  jwksCacheMinutes?: number;
  /** At most one key set fetch per this many seconds. Default 30. */
  jwksMinRefreshSeconds?: number;
  /** A key set this old is still used while eSignet's JWKS cannot be fetched. Default 60. */
  jwksMaxStaleMinutes?: number;
  /** Extra CA certificates (PEM), added to Node's roots. */
  ca?: string | Buffer | Array<string | Buffer>;
  /** Turns TLS verification off. Local test servers only: refused for fayda.et and its sub-domains. */
  insecureTls?: boolean;
  browserBinding?: FaydaBrowserBindingOptions;
  /** Signed proofs of a fresh verification (EDR passenger's faydaProof). Off without a secret. */
  proof?: FaydaProofOptions;
}

export interface ResolvedFaydaOptions {
  enabled: boolean;
  clientId: string;
  issuer: string;
  authorizationEndpoint: string;
  tokenEndpoint: string;
  userinfoEndpoint: string;
  jwksUri: string;
  /** Undefined when missing or unreadable; see privateKeyProblem. */
  privateKey: KeyObject | undefined;
  privateKeyProblem: string | undefined;
  keyId: string | undefined;
  redirectUris: Record<string, string>;
  defaultChannel: string;
  returnUrls: Record<string, { success: string; failure: string }>;
  scope: string;
  acrValues: string;
  claimsLocales: string;
  uiLocales: string | undefined;
  userinfoClaims: string[];
  prompt: "login" | "consent" | "select_account" | undefined;
  sessionTtlMs: number;
  clockSkewSeconds: number;
  idTokenAlgs: FaydaJwsAlg[];
  userinfoAlgs: FaydaJwsAlg[];
  requireIdToken: boolean;
  requireNonce: boolean;
  enforceAcr: boolean;
  acceptJsonUserinfo: boolean;
  clientAssertion: Required<FaydaClientAssertionOptions>;
  httpTimeoutMs: number;
  jwksCacheMs: number;
  jwksMinRefreshMs: number;
  jwksMaxStaleMs: number;
  ca: string | Buffer | Array<string | Buffer> | undefined;
  insecureTls: boolean;
  browserBinding: Required<FaydaBrowserBindingOptions>;
  proof: { secrets: string[]; ttlMs: number } | undefined;
}

const text = (value: unknown): string => (typeof value === "string" ? value.trim() : "");
const positive = (value: number | undefined, fallback: number): number =>
  typeof value === "number" && Number.isFinite(value) && value > 0 ? value : fallback;
const algs = (value: FaydaJwsAlg[] | undefined): FaydaJwsAlg[] => {
  const list = (value ?? ["RS256"]).filter((a) => (SUPPORTED_JWS_ALGS as readonly string[]).includes(a));
  return list.length > 0 ? list : ["RS256"];
};

/** Fills defaults and trims. Never throws: what is wrong is reported by missingFaydaOptions. */
export function resolveFaydaOptions(options: FaydaModuleOptions): ResolvedFaydaOptions {
  let privateKey: KeyObject | undefined;
  let privateKeyProblem: string | undefined;
  if (options.privateKey === undefined || options.privateKey === null || options.privateKey === "") {
    privateKeyProblem = "missing";
  } else {
    try {
      privateKey = importPrivateKey(options.privateKey);
    } catch (err) {
      privateKeyProblem = err instanceof FaydaError ? err.message : "unreadable";
    }
  }
  const redirectUris: Record<string, string> = {};
  for (const [channel, uri] of Object.entries(options.redirectUris ?? {})) {
    const key = text(channel);
    const value = text(uri);
    if (key && value) redirectUris[key] = value;
  }
  const channels = Object.keys(redirectUris);
  const wantedDefault = text(options.defaultChannel);
  const defaultChannel = wantedDefault || (channels.includes("WEB") ? "WEB" : channels[0] ?? "WEB");
  const returnUrls: Record<string, { success: string; failure: string }> = {};
  for (const [channel, urls] of Object.entries(options.returnUrls ?? {})) {
    if (urls && text(urls.success) && text(urls.failure)) returnUrls[text(channel)] = { success: text(urls.success), failure: text(urls.failure) };
  }
  const assertion = options.clientAssertion ?? {};
  const binding = options.browserBinding ?? {};
  const proofSecrets = options.proof
    ? [options.proof.secret, ...(options.proof.previousSecrets ?? [])].filter((s): s is string => typeof s === "string" && s.length > 0)
    : [];
  return {
    enabled: options.enabled !== false,
    clientId: text(options.clientId),
    issuer: text(options.issuer),
    authorizationEndpoint: text(options.authorizationEndpoint),
    tokenEndpoint: text(options.tokenEndpoint),
    userinfoEndpoint: text(options.userinfoEndpoint),
    jwksUri: text(options.jwksUri),
    privateKey,
    privateKeyProblem,
    keyId: text(options.keyId) || undefined,
    redirectUris,
    defaultChannel,
    returnUrls,
    scope: text(options.scope) || FAYDA_DEFAULT_SCOPE,
    acrValues: text(options.acrValues) || FAYDA_DEFAULT_ACR,
    claimsLocales: text(options.claimsLocales) || "en am",
    uiLocales: text(options.uiLocales) || undefined,
    userinfoClaims:
      options.userinfoClaims && options.userinfoClaims.length > 0
        ? options.userinfoClaims.map(text).filter(Boolean)
        : [...FAYDA_DEFAULT_USERINFO_CLAIMS],
    prompt: options.prompt === false ? undefined : options.prompt ?? "login",
    sessionTtlMs: positive(options.sessionTtlMinutes, 10) * 60_000,
    clockSkewSeconds: typeof options.clockSkewSeconds === "number" && options.clockSkewSeconds >= 0 ? options.clockSkewSeconds : 60,
    idTokenAlgs: algs(options.idTokenAlgs),
    userinfoAlgs: algs(options.userinfoAlgs),
    requireIdToken: options.requireIdToken !== false,
    requireNonce: options.requireNonce !== false,
    enforceAcr: options.enforceAcr === true,
    acceptJsonUserinfo: options.acceptJsonUserinfo === true,
    clientAssertion: {
      alg: assertion.alg === "PS256" ? "PS256" : "RS256",
      typ: assertion.typ === true,
      jti: assertion.jti !== false,
      lifetimeSeconds: Math.min(positive(assertion.lifetimeSeconds, 120), 300),
    },
    httpTimeoutMs: positive(options.httpTimeoutMs, 10_000),
    jwksCacheMs: positive(options.jwksCacheMinutes, 10) * 60_000,
    jwksMinRefreshMs: positive(options.jwksMinRefreshSeconds, 30) * 1000,
    jwksMaxStaleMs: positive(options.jwksMaxStaleMinutes, 60) * 60_000,
    ca: options.ca,
    insecureTls: options.insecureTls === true,
    browserBinding: {
      unboundChannels: (binding.unboundChannels ?? ["MOBILE"]).map(text).filter(Boolean),
      cookiePrefix: text(binding.cookiePrefix) || "fayda_b_",
      cookiePath: text(binding.cookiePath) || "/",
      secureCookie: binding.secureCookie !== false,
      sameSite: binding.sameSite === "Strict" || binding.sameSite === "None" ? binding.sameSite : "Lax",
    },
    proof: proofSecrets.length > 0 ? { secrets: proofSecrets, ttlMs: positive(options.proof?.ttlMinutes, 15) * 60_000 } : undefined,
  };
}

const LOOPBACK = new Set(["localhost", "127.0.0.1", "::1", "[::1]"]);

function endpointProblem(value: string): string | undefined {
  if (!value) return "missing";
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    return "not a URL";
  }
  if (url.protocol === "https:") return undefined;
  if (url.protocol === "http:" && LOOPBACK.has(url.hostname)) return undefined;
  return "must be https";
}

/**
 * What is missing or unsafe, by option name, never with values. Empty when the options can be
 * used. Checked when the client is built: the app refuses to start rather than fail later.
 */
export function missingFaydaOptions(options: ResolvedFaydaOptions): string[] {
  const problems: string[] = [];
  if (!options.clientId) problems.push("clientId");
  if (!options.issuer) problems.push("issuer");
  for (const name of ["authorizationEndpoint", "tokenEndpoint", "userinfoEndpoint", "jwksUri"] as const) {
    const problem = endpointProblem(options[name]);
    if (problem) problems.push(problem === "missing" ? name : `${name} (${problem})`);
  }
  if (options.privateKeyProblem) {
    problems.push(options.privateKeyProblem === "missing" ? "privateKey" : `privateKey (${options.privateKeyProblem})`);
  }
  const channels = Object.entries(options.redirectUris);
  if (channels.length === 0) problems.push("redirectUris");
  for (const [channel, uri] of channels) {
    try {
      const url = new URL(uri);
      if (url.hash) problems.push(`redirectUris.${channel} (no fragment allowed)`);
    } catch {
      problems.push(`redirectUris.${channel} (not a URL)`);
    }
  }
  if (channels.length > 0 && !options.redirectUris[options.defaultChannel]) problems.push("defaultChannel (not in redirectUris)");
  if (options.insecureTls) {
    for (const name of ["authorizationEndpoint", "tokenEndpoint", "userinfoEndpoint", "jwksUri"] as const) {
      try {
        const host = new URL(options[name]).hostname;
        if (isFaydaProductionHost(host)) {
          problems.push(`insecureTls (refused for ${host})`);
          break;
        }
      } catch {
        // reported above
      }
    }
  }
  if (options.proof && options.proof.secrets.some((s) => s.length < 32)) problems.push("proof.secret (at least 32 characters)");
  return problems;
}
